from PIL import Image
im=Image.open('/home/amao/nextkde/tmp/ui-acceptance/calendar/r128-dark-band.png').convert('RGB')
px=im.load()
def runs(Y,x0=262,x1=1100):
    out=[];prev=None;start=x0
    for x in range(x0,x1):
        c=px[x,Y]
        k='F' if (c!=(30,30,30) and c!=(37,37,37)) else '.'
        if k!=prev:
            if prev is not None: out.append((start,x-1,px[x-1,Y]))
            prev=k;start=x
    out.append((start,x1-1,px[x1-1,Y]))
    return [r for r in out if r[0]!=r[1] or r[2]!=(30,30,30)]
for Y in (159,160,184,185,209,210):
    print('y=%d'%Y, runs(Y))
print('--- rule horizontal extents (row y) ---')
for Y in (155,232,233,234):
    row=[px[x,Y] for x in range(0,1100)]
    # find where value departs from plane
    vals={}
    for x,c in enumerate(row):
        vals.setdefault(c,[]).append(x)
    for c,xs in sorted(vals.items(), key=lambda kv:-len(kv[1]))[:3]:
        print(' y=%d'%Y, c, 'n=%d'%len(xs), 'x %d..%d'%(xs[0],xs[-1]))
EOF

